class Color:
    def __init__(self, h, s, l, a=1):
        self.h = hue(h)
        self.s = clamp(s)
        self.l = clamp(l)
        self.a = clamp(a)

    @classmethod
    def rgb(cls, r, g, b, a=1):
        r, g, b = (byte(v)/255 for v in (r,g,b))
        high, low = max(r,g,b), min(r,g,b)
        delta = high-low
        l = (high+low)/2
        if delta == 0:
            return cls(0,0,l,a)
        s = delta/(1-abs(2*l-1))
        if high == r:
            h = 60*((g-b)/delta % 6)
        elif high == g:
            h = 60*((b-r)/delta+2)
        else:
            h = 60*((r-g)/delta+4)
        return cls(h,s,l,a)

