            return (float('nan'),)*3
        h1 = h/60
        x = c*(1-abs(h1 % 2-1))
        m = l-c/2
        if h1 < 1: rgb=(c,x,0)
        elif h1 < 2: rgb=(x,c,0)
        elif h1 < 3: rgb=(0,c,x)
        elif h1 < 4: rgb=(0,x,c)
        elif h1 < 5: rgb=(x,0,c)
        else: rgb=(c,0,x)
        return tuple(v+m for v in rgb)

