    def xyz(self):
        return matmul(RGB_XYZ,tuple(lin(v) for v in self.floats()))

    @classmethod
    def from_xyz(cls, xyz, a=1):
        return cls.rgb_float(*(delinear(v) for v in matmul(XYZ_RGB,xyz)),a=a)

    def lab(self):
        x,y,z=self.xyz()
        def f(t):
            return t**(1/3) if t>.008856 else 7.787*t+16/116
        x,y,z=f(x/.95047),f(y),f(z/1.08883)
        return (116*y-16,500*(x-y),200*(y-z))

    @classmethod
    def from_lab(cls, L, A, B, a=1):
