def parse(text):
    text=text.strip()
    named=text.lower()
    named=ALIASES.get(named,named)
    if named in NAMES:
        text=NAMES[named]
    if re.fullmatch(r'#?(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})',text):
        v=text.lstrip('#')
        if len(v) in (3,4): v=''.join(c*2 for c in v)
        rgba=[int(v[i:i+2],16) for i in range(0,len(v),2)]
        return Color.rgb(*rgba[:3],a=rgba[3]/255 if len(rgba)==4 else 1)
    m=re.fullmatch(r'([a-zA-Z]+)\((.*)\)',text,re.S)
    name,body=(m[1],m[2]) if m else ('rgb',text)
    if name not in ('rgb','rgba','hsl','hsla','hsv','hsva','gray','lab','Lab','lch','LCh','oklab','OkLab','oklch','OkLCh'):
        raise ValueError(text)
    parts=re.split(r'\s*,\s*|\s+',body.strip())
    tokens=[TOKEN.fullmatch(part) for part in parts]
    if not all(tokens): raise ValueError(text)
    v=[float(m[1]) for m in tokens]
    units=[m[2] for m in tokens]
    if name=='gray':
        if len(v)!=1 or units[0] not in (None,'%'): raise ValueError(text)
        return Color(0,0,v[0]/100 if units[0] else v[0])
    if len(v) not in (3,4): raise ValueError(text)
    a=1
    if len(v)==4:
        if units[3] not in (None,'%'): raise ValueError(text)
        a=v[3]/100 if units[3] else v[3]
    if name.startswith('rgb'):
        if not (units[:3]==[None]*3 or units[:3]==['%']*3): raise ValueError(text)
        if units[0]: v[:3]=[x*255/100 for x in v[:3]]
        return Color.rgb(*v[:3],a=a)
    if name.startswith('hsl') or name.startswith('hsv'):
        if units[1:3]!=['%','%'] or units[0]=='%': raise ValueError(text)
        h=v[0]*{None:1,'deg':1,'grad':.9,'rad':180/math.pi,'turn':360,'°':1}[units[0]]
        if name.startswith('hsv'): return Color.hsv(h,v[1]/100,v[2]/100,a)
        return Color(h,v[1]/100,v[2]/100,a)
    if any(units[:3]): raise ValueError(text)
    if name.lower()=='lab': return Color.from_lab(*v[:3],a=a)
    if name.lower()=='oklab': return Color.from_oklab(*v[:3],a=a)
    return Color.from_lch(*v[:3],a=a,ok=name.lower()=='oklch')


def interpolate(first,second,t,space='lab'):
    t=clamp(t)
    a=first.a+(second.a-first.a)*t
    def lerp(p,q): return tuple(x+(y-x)*t for x,y in zip(p,q))
    if space=='rgb':
        return Color.rgb_float(*lerp(first.floats(),second.floats()),a=a)
    if space=='hsl':
        h1,h2=first.h,second.h
        if first.s==0: h1=h2
        if second.s==0: h2=h1
        h=h1+((h2-h1+180)%360-180)*t
        return Color(h,first.s+(second.s-first.s)*t,first.l+(second.l-first.l)*t,a)
    if space=='lch':
        l1,c1,h1=first.lch(); l2,c2,h2=second.lch()
        h=h1+((h2-h1+180)%360-180)*t
