                    if attached is None:
                        if i<len(args) and (not args[i].startswith('-') or args[i]=='-'):
                            attached=args[i];i+=1
                        elif i<len(args) and args[i].startswith('-') and args[i] not in ('--help','-h'):
                            unknown(cmd,args[i] if args[i].startswith('--') else args[i][:2],pos,opts)
                        else:
                            text=f"error: a value is required for '{label}' but none was supplied\n"
                            if choices:text+='  [possible values: '+', '.join(choices)+']\n'
                            raise CliError(text+'\n'+FOOT)
                    if choices: attached=enum_value(attached,choices,label,insensitive)
                    opts[name]=attached
                else:
                    if attached is not None:
                        raise CliError(f"error: unexpected value '{attached}' for '{label}' found; no more were expected\n\n"+usage(cmd,opts,pos)+'\n'+FOOT)
                    opts[name]=True
            continue
        if cmd=='main':
            if arg not in COMMANDS and arg!='colour':unknown_command(arg)
            cmd='color' if arg=='colour' else arg
            globalopts=opts;opts={};stop=False
            continue
        if cmd=='help':
            if arg not in COMMANDS and arg!='colour':unknown_command(arg)
            if pos: unknown_command(arg)
            pos.append('color' if arg=='colour' else arg);continue
        if len(pos)>=MAXPOS.get(cmd,100000000):unknown(cmd,arg,pos,opts)
        pos.append(arg)
        if len(pos)==1:
            if cmd=='format':enum_value(arg,FORMATS,'[type]',True)
            elif cmd=='set':enum_value(arg,PROPERTIES,'<property>',True)
            elif cmd=='sort-by':enum_value(arg,SORTS,'[sort-order]')
            elif cmd=='colorblind':enum_value(arg,['prot','deuter','trit'],'<type>',True)
    if cmd=='main':
        show_help('main',True,sys.stderr);raise SystemExit(2)
    if cmd=='help':show_help(pos[0] if pos else 'main');raise SystemExit(0)
    needed=REQUIRED.get(cmd,[])
    if len(pos)<len(needed):
        text='error: the following required arguments were not provided:\n'+''.join('  '+a+'\n' for a in needed[len(pos):])+'\n'
        raise CliError(text+usage(cmd,opts,pos,True)+'\n'+FOOT)
    return cmd,pos,opts,globalopts


def number(s,integer=False):
    try:
        if s!=s.strip():raise ValueError()
        if integer:
            if not re.fullmatch(r'\+?\d+',s):raise ValueError()
            n=int(s)
            if n>18446744073709551615:raise ValueError()
            return n
        if not re.fullmatch(NUMBER+r'|[+-]?(?:inf(?:inity)?|nan)',s,re.I):raise ValueError()
        return float(s)
    except (ValueError,OverflowError):raise AppError(f"Could not parse number '{s}'")


def pick_spectrum():
    sys.stderr.write(' '*52+'\n'+('   '+'▀'*48+' \n')*25+'\n')


def read_color(text):
    if text=='-':
        text=sys.stdin.readline()
        if text=='':raise AppError('Could not read color from standard input')
    elif text=='pick':
        pick_spectrum()
        raise AppError("Could not find any external color picker tool. See 'pastel pick --help' for more information.")
    text=text.strip()
    try:return parse(text)
    except (ValueError,KeyError,OverflowError):raise AppError(f"Could not parse color '{text}'")


def input_colors(args):
    if args:
        for text in args:yield read_color(text)
    else:
        for text in sys.stdin:
            yield read_color(text.strip())


def styled(text,fg=None,bg=None,bold=False,italic=False,underline=False,mode=None):
    mode=mode or MODE
    if mode=='off':return text
    codes=[]
    if fg is not None:codes.append(fg.ansi_fg(mode))
    if bg is not None:codes.append(bg.ansi_fg(mode,True))
    if bold:codes.append('1')
    if italic:codes.append('3')
    if underline:codes.append('4')
    if not codes:return text
    return '\x1b['+';'.join(codes)+'m'+text+'\x1b[0m'


def pixel(top,bottom,mode=None):
    return styled(' ' if top.ints()==bottom.ints() else '▀',top,bottom,mode=mode)


def display_color(c):
    global STARTED
    if not sys.stdout.isatty():
        print(c.hsl(False));return
    nearest=c.nearest()[:3]
    exact=next((n for n in NAMES if parse(NAMES[n]).ints()==c.ints()),None)
    lines=[]
    if exact:lines.append('Name: '+exact)
    lines += ['Hex: '+c.hex(), 'RGB: '+c.format('rgb'), 'HSL: '+c.hsl(), '', 'Most similar:']
    for name,d in nearest:
        if name!=exact:
            n=parse(NAMES[name]);lines.append(' '+''.join(pixel(n,n) for _ in range(5))+' '+name)
    if not STARTED:sys.stdout.write('\n');STARTED=True
    a=Color.rgb(240,240,240);b=Color.rgb(181,181,181)
    def composite(bg):
        r=c.floats();v=bg.floats()
        return Color.rgb_float(*(x*c.a+y*(1-c.a) for x,y in zip(r,v)))
    ca,cb=composite(a),composite(b)
    for y in range(8):
        panel=''
        for x in range(16):
            light,dark=(a,b) if x%2==0 else (b,a)
            if y not in (0,7) and 2<=x<14:
                light,dark=(ca,cb) if x%2==0 else (cb,ca)
            panel+=pixel(light,dark)
        line=lines[y] if y<len(lines) else ''
        width=len(re.sub(r'\x1b\[[0-9;]*m','',line))
        sys.stdout.write('  '+panel+'  '+line+' '*max(0,40-width)+'\n')
    sys.stdout.write('\n')


def sort_colors(colors,order):
    if order=='random':random.shuffle(colors);return colors
    if order=='brightness':key=lambda c:c.brightness()
    elif order=='luminance':key=lambda c:c.luminance()
    elif order=='chroma':key=lambda c:c.lch()[1]
    else:key=lambda c:c.lch()[2]
    return sorted(colors,key=key)


def print_format(c,f):
    text=c.format(f)
    if f.endswith('-escapecode'):
        sys.stdout.write(text)
    else:
        print(styled(text,c.textcolor(),c))


def paint(pos,opts):
    fg=read_color(pos[0]);bg=read_color(opts['on']) if 'on' in opts else None
    style={'fg':fg,'bg':bg,'bold':opts.get('bold',False),'italic':opts.get('italic',False),'underline':opts.get('underline',False)}
    if len(pos)>1:
        sys.stdout.write(styled(' '.join(pos[1:]),**style))
        if not opts.get('no-newline'):sys.stdout.write('\n')
    else:
        for line in sys.stdin:
            line=line.rstrip('\r\n')
            sys.stdout.write(styled(line,**style))
            if not opts.get('no-newline'):sys.stdout.write('\n')


def run(cmd,pos,opts):
    if cmd=='colorcheck':
        colorcheck();return
    if cmd=='paint':paint(pos,opts);return
    if cmd=='gray':display_color(Color(0,0,number(pos[0])));return
    if cmd=='pick':
        n=number(pos[0] if pos else '1',True)
        pick_spectrum()
        if n:raise AppError("Could not find any external color picker tool. See 'pastel pick --help' for more information.")
        return
    if cmd=='list':
        order=opts.get('sort','hue')
        colors=sort_colors([parse(v) for v in NAMES.values()],order)
        namebyrgb={parse(v).ints():k for k,v in NAMES.items()}
        for c in colors:
            if sys.stdout.isatty():display_color(c)
            else:print(namebyrgb[c.ints()])
        return
    if cmd=='gradient':
        n=number(opts.get('number','10'),True)
        if n<2:raise ValueError('count')
        if len(pos)<2:raise AppError('The number of color arguments must be larger than one')
        colors=[read_color(c) for c in pos]
        space=opts.get('colorspace','lab')
        for i in range(n):
            p=i/(n-1)*(len(colors)-1)
            index=min(int(p),len(colors)-2)
            display_color(interpolate(colors[index],colors[index+1],p-index,space))
        return
    if cmd=='random':
        n=number(opts.get('number','10'),True);strategy=opts.get('strategy','vivid')
        for _ in range(n):
            if strategy=='gray':c=Color.rgb(*(random.randrange(256),)*3)
            elif strategy=='rgb':c=Color.rgb(*(random.randrange(256) for _ in range(3)))
            elif strategy=='lch_hue':c=Color.from_lch(70,50,random.random()*360)
            else:c=Color(random.random()*360,random.uniform(.5,1),random.uniform(.3,.7))
            display_color(c)
        return
    if cmd=='distinct':
        n=number(pos[0] if pos else '10',True)
        if n<2:raise AppError('The number of colors must be larger than one')
        fixedcols=list(input_colors(pos[1:] if pos else []))
        if len(fixedcols)>n:raise AppError('The number of fixed colors must be smaller than the total number of colors')
        colors=fixedcols[:]
        while len(colors)<n:
            choices=[Color.rgb(*(random.randrange(256) for _ in range(3))) for _ in range(150)]
            if colors:
                old=[c.lab() for c in colors]
                c=max(choices,key=lambda c:min(delta_e_2000(c.lab(),l) for l in old))
            else:c=random.choice(choices)
            colors.append(c)
        for c in sort_colors(colors,'hue'):display_color(c)
        return
    offset={'colorblind':1,'darken':1,'desaturate':1,'format':1,'lighten':1,'mix':1,'rotate':1,'saturate':1,'set':2,'sort-by':1}.get(cmd,0)
    colorargs=pos[offset:]
    if cmd=='sort-by':
        colors=sort_colors(list(input_colors(colorargs)),pos[0] if pos else 'hue')
        if opts.get('reverse'):colors.reverse()
        if opts.get('unique'):
            seen=set();new=[]
            for c in colors:
                if c.ints() not in seen:new.append(c);seen.add(c.ints())
            colors=new
        for c in colors:display_color(c)
        return
    for c in input_colors(colorargs):
        if cmd=='format':
            print_format(c,pos[0].lower() if pos else 'hex');continue
        if cmd=='colorblind':c=colorblind(c,pos[0].lower())
        elif cmd=='complement':c=c.with_hsl(h=c.h+180)
        elif cmd=='rotate':c=c.with_hsl(h=c.h+number(pos[0]))
        elif cmd in ('lighten','darken'):c=c.with_hsl(l=c.l+number(pos[0])*(1 if cmd=='lighten' else -1))
        elif cmd in ('saturate','desaturate'):c=c.with_hsl(s=c.s+number(pos[0])*(1 if cmd=='saturate' else -1))
        elif cmd=='to-gray':c=c.to_gray()
        elif cmd=='textcolor':c=c.textcolor()
        elif cmd=='set':c=set_property(c,pos[0].lower(),number(pos[1]))
        elif cmd=='mix':
            f=number(opts.get('fraction','0.5'))
            c=interpolate(c,read_color(pos[0]),f,opts.get('colorspace','lab'))
        display_color(c)


def colorcheck():
    print('8-bit mode:')
    for mode in ['8bit','24bit']:
        if mode=='24bit':print('24-bit mode:')
        print(' '*30)
        cols=[parse('#492732'),parse('#10331e'),parse('#1d365a')]
        for _ in range(4):
            line=''
            for i,c in enumerate(cols):
