            print(line)
        print(' '*30)
    print('If your terminal emulator supports 24bit colors, you should see three square color panels in the lower row and the colors should look similar (but slightly different from) the colors in the top row panels.')


def main():
    global MODE
    try:
        cmd,pos,opts,g=parse_cli(sys.argv[1:])
        MODE=g.get('color-mode','auto')
        if g.get('force-color'):MODE='24bit'
        if MODE=='auto':
            MODE='off'
            if sys.stdout.isatty() and 'NO_COLOR' not in os.environ:
                MODE='24bit' if os.environ.get('COLORTERM','').lower() in ('truecolor','24bit') else '8bit'
        run(cmd,pos,opts)
    except CliError as e:
        sys.stderr.write(e.text);return 2
    except AppError as e:
        sys.stderr.write('[pastel error]: '+str(e)+'\n');return 1
    except ValueError as e:
        if str(e)=='count':sys.stderr.write('[pastel error]: The specified color count must be larger than one\n');return 1
        raise
    except BrokenPipeError:
        try:sys.stdout.close()
        except BrokenPipeError:pass
        return 0
    return 0


if __name__=='__main__':
    sys.exit(main())
