class AppError(Exception):
    pass


class CliError(Exception):
    def __init__(self,text): self.text=text


def jaro(a,b):
    if a==b: return 1.0
    if not a or not b:return 0.0
    radius=max(len(a),len(b))//2-1
    aa=[False]*len(a);bb=[False]*len(b)
    for i,c in enumerate(a):
        for j in range(max(0,i-radius),min(i+radius+1,len(b))):
            if not bb[j] and c==b[j]:
                aa[i]=True;bb[j]=True;break
    m=sum(aa)
    if not m:return 0.0
    left=[x for x,ok in zip(a,aa) if ok];right=[x for x,ok in zip(b,bb) if ok]
    trans=sum(x!=y for x,y in zip(left,right))/2
    score=(m/len(a)+m/len(b)+(m-trans)/m)/3
    prefix=0
    for x,y in zip(a[:4],b[:4]):
        if x!=y:break
        prefix+=1
    return score+.1*prefix*(1-score)


def suggestions(value,choices):
    return [x for x in sorted(choices,key=lambda x:jaro(value,x)) if jaro(value,x)>.8]


def enum_value(value,choices,arg,insensitive=False):
    for c in choices:
        if value==c or (insensitive and value.lower()==c.lower()):
            return c.lower() if insensitive else c
    text=f"error: invalid value '{value}' for '{arg}'\n  [possible values: {', '.join(choices)}]\n\n"
    ss=suggestions(value,choices)
    if ss:
        text+="  tip: a similar value exists: '"+ss[-1]+"'\n\n"
    raise CliError(text+FOOT)


def show_help(cmd='main',long=True,stream=None):
    if cmd=='help':
        text='Print this message or the help of the given subcommand(s)\n\nUsage: executable help [COMMAND]...\n\nArguments:\n  [COMMAND]...  Print help for the subcommand(s)\n'
    else:text=HELP[cmd]['long' if long else 'short']
    (stream or sys.stdout).write(text.replace('executable',PROG))


# Option definitions: long name, short alias, value placeholder, enumeration, case-insensitive.
GLOBAL=[('color-picker',None,'color-picker',PICKERS,False),('force-color','f',None,None,False),('color-mode','m','mode',['24bit','8bit','off','auto'],False)]
OPTIONS={
    'mix':[('colorspace','s','name',SPACES,True),('fraction','f','fraction',None,False)],
    'gradient':[('number','n','count',None,False),('colorspace','s','name',SPACES,True)],
    'random':[('strategy','s','strategy',['vivid','rgb','gray','lch_hue'],False),('number','n','count',None,False)],
    'list':[('sort','s','sort-order',SORTS,False)],
    'sort-by':[('reverse','r',None,None,False),('unique','u',None,None,False)],
    'paint':[('on','o','bg-color',None,False),('bold','b',None,None,False),('italic','i',None,None,False),('underline','u',None,None,False),('no-newline','n',None,None,False)],
    'distinct':[('metric','m','name',['CIEDE2000','CIE76'],False),('verbose','v',None,None,False)],
}
USAGES={
 'main':'[OPTIONS] <COMMAND>', 'color':'[color]...', 'colorblind':'<type> [color]...',
 'colorcheck':'', 'complement':'[color]...', 'darken':'<amount> [color]...', 'desaturate':'<amount> [color]...',
 'distinct':'[OPTIONS] [count] [color]...', 'format':'[type] [color]...', 'gradient':'[OPTIONS] <color>...',
 'gray':'<lightness>', 'lighten':'<amount> [color]...', 'list':'[OPTIONS]', 'mix':'[OPTIONS] <color> [color]...',
 'paint':'[OPTIONS] <color> [text]...', 'pick':'[count]', 'random':'[OPTIONS]', 'rotate':'<degrees> [color]...',
 'saturate':'<amount> [color]...', 'set':'<property> <value> [color]...', 'sort-by':'[OPTIONS] [sort-order] [color]...',
 'textcolor':'[color]...', 'to-gray':'[color]...', 'help':'[COMMAND]...'
}
REQUIRED={'colorblind':['<type>'],'darken':['<amount>'],'desaturate':['<amount>'],'gradient':['<color>...'],'gray':['<lightness>'],'lighten':['<amount>'],'mix':['<color>'],'paint':['<color>'],'rotate':['<degrees>'],'saturate':['<amount>'],'set':['<property>','<value>']}
MAXPOS={'gray':1,'pick':1,'list':0,'random':0,'colorcheck':0}


def usage(cmd,opts=None,pos=None,missing=False):
    pattern=USAGES[cmd]
    if missing:pattern=pattern.replace('[OPTIONS] ','')
    if pos:
        for i,arg in enumerate({'format':['type'],'sort-by':['sort-order'],'distinct':['count'],'pick':['count']}.get(cmd,[])):
            if len(pos)>i:pattern=pattern.replace('['+arg+']','<'+arg+'>')
    return 'Usage: '+PROG+(' '+cmd if cmd!='main' else '')+(' '+pattern if pattern else '')+'\n'


def unknown(cmd,arg,pos=None,opts=None):
    text=f"error: unexpected argument '{arg}' found\n\n"
    options=GLOBAL if cmd=='main' else OPTIONS.get(cmd,[])
    ss=suggestions(arg,['--'+v[0] for v in options]+['--help']) if arg.startswith('--') else []
    if ss:
        text+=f"  tip: a similar argument exists: '{ss[-1]}'\n\n"
    elif arg.startswith('-') and cmd not in ('main','list','random','colorcheck','help'):
        text+=f"  tip: to pass '{arg}' as a value, use '-- {arg}'\n\n"
    raise CliError(text+usage(cmd,opts,pos)+'\n'+FOOT)


def unknown_command(cmd):
    text=f"error: unrecognized subcommand '{cmd}'\n\n"
    ss=suggestions(cmd,COMMANDS+['colour'])
    if len(ss)>1:text+="  tip: some similar subcommands exist: "+', '.join(repr(v) for v in ss)+"\n\n"
    elif ss:text+="  tip: a similar subcommand exists: '"+ss[0]+"'\n\n"
    raise CliError(text+usage('main')+'\n'+FOOT)


def parse_cli(args):
    cmd='main';pos=[];opts={};globalopts={};stop=False
    i=0
    while i<len(args):
        arg=args[i];i+=1
        if not stop and arg=='--':stop=True;continue
        if not stop and arg.startswith('-') and arg!='-':
            if arg in ('-h','--help'):
